//! Generates starter `BlockSchema` snippets from corpus observations.
//!
//! The output is deliberately conservative: inferred kinds/defaults are marked
//! as auto-generated, labels fall back to XML names, and unknown child elements
//! are emitted as TODO comments. It is meant to be reviewed and refined, not
//! pasted blindly into the knowledge base.

use anyhow::{bail, Result};
use loxone_core::block_schema::{lookup_block_schema, ChildConfigKind};
use loxone_core::model::{classify_pin_kind, PinKind};

use crate::report::Coverage;
use crate::stats::{AttrStats, CorpusStats, PinStats, TypeStats};

#[derive(Debug, Clone, Default)]
pub struct GenOptions {
    /// Generate only these types. Empty means every unknown non-structural type.
    pub types: Vec<String>,
    /// Also emit snippets for types that already have a schema.
    pub include_known: bool,
    /// Also emit metadata/caption/section types that do not look like blocks.
    pub include_non_block: bool,
    /// Keep structural attributes such as `U`, `Title`, `Px`, ...
    pub include_generic_attributes: bool,
}

const GENERIC_ATTRIBUTES: &[&str] = &[
    "U", "Title", "Type", "Px", "Py", "Px2", "Py2", "Cl", "Ref", "SL", "DateS", "CDate",
];

pub fn generate_rust(stats: &CorpusStats, options: &GenOptions) -> Result<String> {
    let coverage = Coverage::build(stats);
    let selected: Vec<String> = if options.types.is_empty() {
        if options.include_known {
            stats
                .types
                .iter()
                .filter(|(type_name, type_stats)| {
                    !crate::dom::is_structural_type(type_name)
                        && (options.include_non_block
                            || crate::report::is_schema_candidate(type_name, type_stats))
                })
                .map(|(type_name, _)| type_name.clone())
                .collect()
        } else {
            coverage
                .unknown_types
                .iter()
                .filter(|item| options.include_non_block || item.schema_candidate)
                .map(|item| item.type_name.clone())
                .collect()
        }
    } else {
        options.types.clone()
    };

    if selected.is_empty() {
        bail!(
            "no types selected (corpus contains no unknown block/periphery types; use --include-non-block for metadata types)"
        );
    }

    let mut out = String::new();
    out.push_str("// Auto-generated by `loxone-format-lab gen`.\n");
    out.push_str("// Review labels, units, descriptions, and enum values against the Loxone KB.\n");
    out.push_str("// Paste the entries below into `crates/loxone-core/src/block_schema.rs`.\n\n");

    for type_name in selected {
        let Some(type_stats) = stats.types.get(&type_name) else {
            out.push_str(&format!(
                "// SKIPPED `{type_name}`: not observed in the scanned corpus.\n\n"
            ));
            continue;
        };
        if !options.include_known && lookup_block_schema(&type_name).is_some() {
            out.push_str(&format!(
                "// SKIPPED `{type_name}`: schema already exists (use --include-known to emit anyway).\n\n"
            ));
            continue;
        }
        out.push_str(&generate_type(&type_name, type_stats, options));
    }

    Ok(out)
}

fn generate_type(type_name: &str, stats: &TypeStats, options: &GenOptions) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "// `{}` observed {} time(s) in {:?}\n",
        comment_text(type_name),
        stats.occurrences,
        stats.root_sections
    ));

    let mut attrs: Vec<(&String, &AttrStats)> = stats
        .attributes
        .iter()
        .filter(|(name, _)| {
            options.include_generic_attributes || !GENERIC_ATTRIBUTES.contains(&name.as_str())
        })
        .collect();
    attrs.sort_by(|a, b| b.1.count.cmp(&a.1.count).then_with(|| a.0.cmp(b.0)));

    let mut pin_params: Vec<(&String, &PinStats)> = stats
        .pins
        .iter()
        .filter(|(key, pin)| pin.defaults.count > 0 && !pin.is_probably_output(key))
        .collect();
    pin_params.sort_by(|a, b| b.1.occurrences.cmp(&a.1.occurrences).then_with(|| a.0.cmp(b.0)));

    let mut pin_docs: Vec<(&String, &PinStats)> = stats.pins.iter().collect();
    pin_docs.sort_by(|a, b| b.1.occurrences.cmp(&a.1.occurrences).then_with(|| a.0.cmp(b.0)));

    let child_configs = infer_child_configs(stats);
    for tag in stats.children.keys() {
        if tag != "C" && !child_configs.iter().any(|kind| child_config_matches(*kind, tag)) {
            out.push_str(&format!(
                "// TODO: unknown child element <{}> observed {}x\n",
                comment_text(tag),
                stats.children[tag].count
            ));
        }
    }

    out.push_str("schema!(\n");
    out.push_str(&format!("    {},\n", rust_str(type_name)));
    out.push_str(&format!("    {},\n", rust_str(&format!("{type_name} (auto)"))));
    out.push_str("    \"Uncategorized\",\n");
    out.push_str("    \"\",\n");
    out.push_str(&format!(
        "    {},\n",
        rust_str("Auto-generated from corpus observations; replace with official Loxone KB text.")
    ));

    out.push_str("    &[\n");
    for (name, attr) in attrs {
        let kind = value_kind(attr);
        let default = default_expr(name, attr);
        out.push_str(&format!(
            "        // {}x, {} distinct, examples: {}\n",
            attr.count,
            attr.distinct,
            example_comment(attr)
        ));
        out.push_str(&format!(
            "        attr!({}, {}, None, {}, {}, {}),\n",
            rust_str(name),
            rust_str(name),
            kind,
            default,
            rust_str(&format!(
                "Observed in {} of {} {} nodes.",
                attr.count, stats.occurrences, type_name
            ))
        ));
    }
    out.push_str("    ],\n");

    out.push_str("    &[\n");
    for (key, pin) in pin_params {
        let default = pin
            .defaults
            .most_common()
            .map(|(value, _)| value)
            .unwrap_or_default();
        out.push_str(&format!(
            "        param!({}, {}, None, {}, {}, {}),\n",
            rust_str(key),
            rust_str(key),
            value_kind(&pin.defaults),
            rust_str(default),
            rust_str(&format!(
                "Observed on {} of {} {} nodes.",
                pin.occurrences, stats.occurrences, type_name
            ))
        ));
    }
    out.push_str("    ],\n");

    out.push_str("    &[\n");
    for (key, pin) in pin_docs {
        let direction = pin_direction(key, pin);
        let macro_name = match direction {
            PinKind::Output => "pin_out",
            _ => "pin_in",
        };
        out.push_str(&format!(
            "        {}!({}, {}, {}),\n",
            macro_name,
            rust_str(key),
            rust_str(key),
            rust_str(&format!(
                "Observed on {} of {} {} nodes; {} incoming link(s).",
                pin.occurrences, stats.occurrences, type_name, pin.incoming_links
            ))
        ));
    }
    out.push_str("    ],\n");

    out.push_str("    &[");
    for (index, kind) in child_configs.iter().enumerate() {
        if index > 0 {
            out.push_str(", ");
        }
        out.push_str(&format!("ChildConfigKind::{kind:?}"));
    }
    out.push_str("],\n");
    out.push_str("),\n\n");
    out
}

fn pin_direction(key: &str, pin: &PinStats) -> PinKind {
    if pin.is_probably_output(key) {
        PinKind::Output
    } else {
        let default = (pin.defaults.count > 0).then_some("0");
        classify_pin_kind(key, default, pin.incoming_links > 0, false)
    }
}

fn value_kind(attr: &AttrStats) -> String {
    match attr.inferred_kind() {
        "bool" => "ValueKind::Bool".to_string(),
        "int" => "ValueKind::Int".to_string(),
        "float" => "ValueKind::Float".to_string(),
        "uuid" => "ValueKind::UuidRef".to_string(),
        "enum" => {
            let variants = attr
                .enum_values()
                .into_iter()
                .map(|value| format!("({}, {})", rust_str(&value), rust_str(&value)))
                .collect::<Vec<_>>()
                .join(", ");
            format!("ValueKind::Enum(&[{variants}])")
        }
        _ => "ValueKind::Text".to_string(),
    }
}

fn default_expr(name: &str, attr: &AttrStats) -> String {
    if GENERIC_ATTRIBUTES.contains(&name) {
        return "None".to_string();
    }
    let Some((value, count)) = attr.most_common() else {
        return "None".to_string();
    };
    let stable = count * 10 >= attr.count * 9;
    let kind_is_structured = matches!(
        attr.inferred_kind(),
        "bool" | "int" | "float" | "enum"
    );
    if stable && (kind_is_structured || attr.distinct == 1) {
        format!("Some({})", rust_str(value))
    } else {
        "None".to_string()
    }
}

fn infer_child_configs(stats: &TypeStats) -> Vec<ChildConfigKind> {
    let mut kinds = Vec::new();
    for tag in stats.children.keys() {
        if let Some(kind) = infer_child_config(tag) {
            if !kinds.contains(&kind) {
                kinds.push(kind);
            }
        }
    }
    kinds
}

fn infer_child_config(tag: &str) -> Option<ChildConfigKind> {
    if tag.eq_ignore_ascii_case("HCL") {
        Some(ChildConfigKind::Hcl)
    } else if tag.eq_ignore_ascii_case("PSD") {
        Some(ChildConfigKind::Psd)
    } else if matches!(tag, "Logger" | "Mailer" | "LoggerMailer") {
        Some(ChildConfigKind::LoggerMailer)
    } else if tag == "IoData" {
        Some(ChildConfigKind::IoData)
    } else if tag == "CoHist" {
        Some(ChildConfigKind::CoHist)
    } else if tag.to_ascii_lowercase().contains("lightscene") {
        Some(ChildConfigKind::LightScenes)
    } else if tag.eq_ignore_ascii_case("statGrp") {
        Some(ChildConfigKind::StatsGroup)
    } else if tag.eq_ignore_ascii_case("Load") {
        Some(ChildConfigKind::Load)
    } else if tag.eq_ignore_ascii_case("Modes") {
        Some(ChildConfigKind::Modes)
    } else if tag.eq_ignore_ascii_case("Display") {
        Some(ChildConfigKind::Display)
    } else if tag.eq_ignore_ascii_case("Entry") {
        Some(ChildConfigKind::Entry)
    } else if tag.eq_ignore_ascii_case("StateTexts") {
        Some(ChildConfigKind::StateTexts)
    } else if tag.eq_ignore_ascii_case("HP") {
        Some(ChildConfigKind::Hp)
    } else if tag.eq_ignore_ascii_case("PH") {
        Some(ChildConfigKind::Ph)
    } else if tag.eq_ignore_ascii_case("btns") {
        Some(ChildConfigKind::Buttons)
    } else {
        None
    }
}

fn child_config_matches(kind: ChildConfigKind, tag: &str) -> bool {
    infer_child_config(tag).is_some_and(|inferred| inferred == kind)
}

fn example_comment(attr: &AttrStats) -> String {
    attr.examples
        .iter()
        .take(4)
        .map(|value| format!("`{}`", comment_text(value)))
        .collect::<Vec<_>>()
        .join(", ")
}

fn comment_text(value: &str) -> String {
    value.replace(['\r', '\n'], " ").replace("*/", "* /")
}

fn rust_str(value: &str) -> String {
    format!("{value:?}")
}
